    var $$ = function (s) { return Array.prototype.slice.call(root.querySelectorAll(s)); };
    var payI = $('[data-pay]'), startI = $('[data-start]'), endI = $('[data-end]'), yearsI = $('[data-years]');
    var msg = $('[data-msg]'), result = $('[data-result]'), payRead = $('[data-pay-read]');
    var PAY_HINT = payRead.textContent, mode = 'date', lastText = '';

    function comma(n) { return String(Math.round(n)).replace(/\B(?=(\d{3})+(?!\d))/g, ','); }
    function won(n) { return comma(n) + '원'; }
    function digits(s) { return String(s).replace(/\D/g, ''); }
    function korean(n) { // 50,000,000 → 5,000만 원 / 123,456,789 → 1억 2,345만 6,789원
      var eok = Math.floor(n / 1e8), man = Math.floor(n % 1e8 / 1e4), r = n % 1e4, out = [];
      if (eok) out.push(comma(eok) + '억');
      if (man) out.push(comma(man) + '만');
      if (r) out.push(comma(r));
      return (out.join(' ') || '0') + '원';
    }
    function fmt(d) { return d.getFullYear() + '. ' + (d.getMonth() + 1) + '. ' + d.getDate() + '.'; }
    function parseDate(v) {
      if (!/^\d{4}-\d{2}-\d{2}$/.test(v)) return null;
      var p = v.split('-'), d = new Date(+p[0], +p[1] - 1, +p[2]);
      return d.getDate() === +p[2] ? d : null;
    }
    function pct(x) { return (Math.round(x * 1000) / 10).toLocaleString('ko-KR') + '%'; }

    [[1e7, '1천만'], [3e7, '3천만'], [5e7, '5천만'], [1e8, '1억'], [2e8, '2억']].forEach(function (c) {
      var b = document.createElement('button');
      b.type = 'button'; b.className = 'krt-chip'; b.dataset.v = c[0]; b.textContent = c[1];
      b.addEventListener('click', function () { payI.value = comma(c[0]); calc(); });
      $('[data-chips]').appendChild(b);
    });

    function hide(text, bad) {
      result.classList.remove('krt-show');
      msg.textContent = text || '';
      $$('.krt-in').forEach(function (i) { i.classList.toggle('krt-bad', !!bad && bad.indexOf(i) >= 0); });
    }

    function calc() {
      var pay = +digits(payI.value);
      $$('.krt-chip').forEach(function (c) { c.classList.toggle('krt-on', +c.dataset.v === pay); });
      payRead.textContent = pay ? '= ' + korean(pay) : PAY_HINT;
      if (digits(payI.value).length > 13) return hide('퇴직금이 너무 커요. 금액을 다시 확인해 주세요.', [payI]);

      var n, period = '';
      if (mode === 'date') {
        if (!startI.value || !endI.value) return hide('');
        var s = parseDate(startI.value), e = parseDate(endI.value);
        if (!s || !e || s.getFullYear() < 1950 || e.getFullYear() > 2100) return hide('날짜를 다시 확인해 주세요.', [startI, endI]);
        if (e < s) return hide('퇴사일이 입사일보다 앞이에요.', [endI]);
        var sv = serviceYears(s, e);
        n = sv.years;
        if (n > 70) return hide('근속기간이 70년을 넘어요. 날짜를 다시 확인해 주세요.', [startI, endI]);
        var parts = [];
        if (sv.full) parts.push(sv.full + '년');
        if (sv.months) parts.push(sv.months + '개월');
        if (sv.days) parts.push(sv.days + '일');
        period = fmt(s) + ' ~ ' + fmt(e) + ' (' + parts.join(' ') + ')';
      } else {
        if (!yearsI.value) return hide('');
        n = +yearsI.value;
        if (!(n >= 1 && n <= 70)) return hide('근속연수는 1~70년 사이로 넣어 주세요.', [yearsI]);
      }
      if (!payI.value) return hide('');
      if (!pay) return hide('퇴직금을 1원 이상 넣어 주세요.', [payI]);

      var r = compute(pay, n), p70 = r.irp[0];
      hide('');
      $('[data-big]').innerHTML = comma(r.total) + '<small>원</small>';
      $('[data-sub]').innerHTML = '<span class="krt-nw">실수령액 ' + won(r.net) + '</span> · <span class="krt-nw">실효세율 ' + pct(r.total / pay) + '</span>';
      $('[data-lump]').textContent = won(r.total);
      $('[data-irp]').textContent = won(p70.total);
      $('[data-save]').innerHTML = r.total > 0
        ? 'IRP로 옮겨 연금으로 받으면 10년 차까지 받는 몫 기준 <b>' + won(r.total - p70.total) + '</b> 덜 내요. 11년 차부터 받는 몫은 더 줄어요.'
        : '근속연수공제·환산급여공제가 퇴직금보다 커서 낼 세금이 없어요.';

      var set = function (k, v) { root.querySelector('[data-r="' + k + '"]').textContent = v; };
      set('pay', won(pay));
      set('period', mode === 'date' ? period : '직접 입력');
      set('years', n + '년');
      set('yd', '−' + won(r.yd));
      set('conv', won(r.conv));
      set('cd', '−' + won(r.cd));
      set('base', won(r.base));
      set('rate', r.base > 0 ? '과세표준 × ' + Math.round(r.rate * 100) + '%' + (r.prog ? ' − ' + comma(r.prog) + '원' : '') : '과세표준이 0원');
      set('ctax', won(r.ctax));
      set('tax', won(r.tax));
      set('local', won(r.local));
      set('total', won(r.total));
      set('net', won(r.net));
      ['p70', 'p60', 'p50'].forEach(function (k, i) {
        var it = r.irp[i];
        root.querySelector('[data-r="' + k + '"]').innerHTML = won(it.total) + '<small class="krt-td-s">' + won(r.total - it.total) + ' 절감</small>';
      });
      result.classList.add('krt-show');

      lastText = '[퇴직소득세 계산 결과]\n퇴직금: ' + won(pay) + '\n근속연수: ' + n + '년' + (mode === 'date' ? ' (' + period + ')' : '') +
        '\n근속연수공제: ' + won(r.yd) + '\n환산급여: ' + won(r.conv) + '\n환산급여공제: ' + won(r.cd) + '\n과세표준: ' + won(r.base) +
        '\n퇴직소득세: ' + won(r.tax) + '\n지방소득세: ' + won(r.local) + '\n세금 합계: ' + won(r.total) +
        '\n실수령액(일시금): ' + won(r.net) + '\n실효세율: ' + pct(r.total / pay) +
        '\nIRP 연금 수령 시 세금(10년 차까지 70%): ' + won(p70.total) + ' (' + won(r.total - p70.total) + ' 절감)' +
        '\n11~20년 차 60%: ' + won(r.irp[1].total) + ' / 21년 차부터 50%: ' + won(r.irp[2].total);
    }

    payI.addEventListener('input', function () {
      var v = digits(payI.value).slice(0, 14);
      payI.value = v ? comma(+v) : '';
      calc();
    });
    yearsI.addEventListener('input', function () {
      var v = digits(yearsI.value).slice(0, 2);
      if (v !== yearsI.value) yearsI.value = v;
      calc();
    });
    [startI, endI].forEach(function (i) { i.addEventListener('input', calc); i.addEventListener('change', calc); });

    $$('[data-mode]').forEach(function (b) {
      b.addEventListener('click', function () {
        mode = b.dataset.mode;
        $$('[data-mode]').forEach(function (x) { var on = x === b; x.classList.toggle('krt-on', on); x.setAttribute('aria-pressed', on); });
        $('[data-box-date]').hidden = mode !== 'date';
        $('[data-box-year]').hidden = mode !== 'year';
        calc();
      });
    });

    $('[data-reset]').addEventListener('click', function () {
      payI.value = startI.value = endI.value = yearsI.value = '';
      hide(''); calc(); payI.focus();
    });

    $('[data-copy]').addEventListener('click', function () {
      var btn = this;
      function done() { btn.textContent = '복사됐어요 ✓'; setTimeout(function () { btn.textContent = '결과 복사'; }, 1500); }
      function fallback() { var ta = document.createElement('textarea'); ta.value = lastText; ta.setAttribute('readonly', ''); ta.style.position = 'fixed'; ta.style.opacity = '0'; document.body.appendChild(ta); ta.select(); try { document.execCommand('copy'); } catch (e) {} ta.remove(); done(); }
      if (navigator.clipboard && window.isSecureContext) navigator.clipboard.writeText(lastText).then(done, fallback);
      else fallback();
    });
  })();
  </script>
</div>
<!-- 퇴직소득세 계산기 위젯 끝 -->
<h2>퇴직소득세 계산법</h2>
<p>퇴직소득세는 오래 일해서 한꺼번에 받는 돈이라는 점을 고려해 세금을 크게 줄여 주는 방식(연분연승법)으로 계산해요. 소득세법 제48조(퇴직소득공제)와 제55조(기본세율)에 따라 아래 순서로 구해요.</p>
<ol>
  <li><strong>근속연수 세기:</strong> 입사일부터 퇴사일까지 기간이에요. 1년이 안 되는 끝수는 1년으로 올려요. 9년 1일을 일했어도 10년으로 봐요.</li>
  <li><strong>근속연수공제 빼기:</strong> 퇴직금에서 근속연수에 따른 공제를 빼요(아래 표).</li>
  <li><strong>환산급여 구하기:</strong> (퇴직금 − 근속연수공제) × 12 ÷ 근속연수. 1년 치 급여처럼 바꾸는 단계예요.</li>
  <li><strong>환산급여공제 빼기:</strong> 환산급여에서 환산급여공제를 뺀 금액이 과세표준이에요.</li>
  <li><strong>환산산출세액:</strong> 과세표준에 종합소득세와 같은 기본세율(6~45%)을 곱해요.</li>
  <li><strong>퇴직소득세:</strong> 환산산출세액 ÷ 12 × 근속연수. 여기에 지방소득세 10%가 더 붙어요.</li>
</ol>
<p>예를 들어 퇴직금 5,000만 원을 받고 근속연수가 10년이면 이렇게 계산해요.</p>
<ul>
  <li>근속연수공제: 500만 원 + 200만 원 × (10 − 5) = <strong>1,500만 원</strong></li>
  <li>환산급여: (5,000만 원 − 1,500만 원) × 12 ÷ 10 = <strong>4,200만 원</strong></li>
  <li>환산급여공제: 800만 원 + (4,200만 원 − 800만 원) × 60% = <strong>2,840만 원</strong></li>
  <li>과세표준: 4,200만 원 − 2,840만 원 = <strong>1,360만 원</strong></li>
  <li>환산산출세액: 1,360만 원 × 6% = <strong>816,000원</strong></li>
  <li>퇴직소득세: 816,000원 ÷ 12 × 10 = <strong>680,000원</strong>, 지방소득세 <strong>68,000원</strong>, 합계 <strong>748,000원</strong> (실효세율 약 1.5%)</li>
</ul>

<h2>근속연수공제 표</h2>
<p>2023년 1월 1일 이후 퇴직하는 사람부터 크게 오른 공제액이에요. 2026년 11월 현재까지 바뀐 내용은 없어서 2026년·2027년 퇴직도 같은 표를 써요.</p>
<table>
  <thead><tr><th>근속연수</th><th>근속연수공제</th><th>예시</th></tr></thead>
  <tbody>
    <tr><td>5년 이하</td><td>100만 원 × 근속연수</td><td>3년: 300만 원</td></tr>
    <tr><td>5년 초과 10년 이하</td><td>500만 원 + 200만 원 × (근속연수 − 5)</td><td>10년: 1,500만 원</td></tr>
    <tr><td>10년 초과 20년 이하</td><td>1,500만 원 + 250만 원 × (근속연수 − 10)</td><td>20년: 4,000만 원</td></tr>
    <tr><td>20년 초과</td><td>4,000만 원 + 300만 원 × (근속연수 − 20)</td><td>30년: 7,000만 원</td></tr>
