    @media (max-width:420px){.knp{padding:18px;border-radius:16px}.knp .knp-big{font-size:31px}.knp .knp-in{font-size:17px}
      .knp .knp-chip{font-size:12.5px}.knp .knp-table{font-size:12.5px}.knp .knp-table th,.knp .knp-table td{padding:8px 5px}}
